begin;
-- One private main graph per storyteller. Rooms receive independent JSON copies.
create table if not exists public.relationship_templates (
 owner_id uuid primary key references auth.users(id) on delete cascade,
 data jsonb not null check (jsonb_typeof(data)='object' and data ?& array['version','links','npcs'] and jsonb_typeof(data->'links')='array' and jsonb_typeof(data->'npcs')='array' and data @> '{"version":1}'::jsonb),
 updated_at timestamptz not null default now(),
 check (octet_length(data::text)<=2097152)
);
create table if not exists public.room_relationships (
 room_id uuid primary key references public.rooms(id) on delete cascade,
 template_owner_id uuid references public.relationship_templates(owner_id) on delete set null,
 data jsonb not null check (jsonb_typeof(data)='object' and data ?& array['version','links','npcs'] and jsonb_typeof(data->'links')='array' and jsonb_typeof(data->'npcs')='array' and data @> '{"version":1}'::jsonb),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check (octet_length(data::text)<=2097152)
);
alter table public.relationship_templates enable row level security;
alter table public.room_relationships enable row level security;
revoke all on public.relationship_templates,public.room_relationships from public,anon,authenticated;
grant select,insert on public.relationship_templates to authenticated;
grant update(data,updated_at) on public.relationship_templates to authenticated;
grant select on public.room_relationships to authenticated;
grant update(data,updated_at) on public.room_relationships to authenticated;
create policy relationship_template_owner_read on public.relationship_templates for select to authenticated using(owner_id=auth.uid());
create policy relationship_template_owner_create on public.relationship_templates for insert to authenticated with check(owner_id=auth.uid());
create policy relationship_template_owner_update on public.relationship_templates for update to authenticated using(owner_id=auth.uid()) with check(owner_id=auth.uid());
create policy room_relationship_member_read on public.room_relationships for select to authenticated using(app_private.is_room_member(room_id,auth.uid()));
create policy room_relationship_master_update on public.room_relationships for update to authenticated using(app_private.is_room_master(room_id,auth.uid())) with check(app_private.is_room_master(room_id,auth.uid()));

create or replace function public.attach_room_relationships(p_room_id uuid) returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,auth set row_security=off as $$
declare snapshot jsonb;
begin
 if auth.uid() is null or not app_private.is_room_master(p_room_id,auth.uid()) then raise exception 'Only the room storyteller may attach a graph';end if;
 -- Row insertion is idempotent. Reattaching never replaces an existing campaign.
 insert into public.room_relationships(room_id,template_owner_id,data)
 select p_room_id,owner_id,data from public.relationship_templates where owner_id=auth.uid()
 on conflict(room_id) do nothing;
 select data into snapshot from public.room_relationships where room_id=p_room_id;
 if snapshot is null then raise exception 'Create a main relationship template first';end if;
 return snapshot;
end;$$;
revoke all on function public.attach_room_relationships(uuid) from public,anon;
grant execute on function public.attach_room_relationships(uuid) to authenticated;

-- Full durable room archive. Invitation secrets and authentication identifiers
-- are deliberately absent; they are not needed to retain the campaign's contents.
create or replace function public.export_room_archive(p_room_id uuid) returns jsonb
language plpgsql security definer set search_path=pg_catalog,public,auth set row_security=off as $$
declare archive jsonb;
begin
 if auth.uid() is null or not app_private.is_room_master(p_room_id,auth.uid()) then raise exception 'Only the room storyteller may export it';end if;
 select jsonb_build_object(
  'format','parma-room','version',1,'exportedAt',now(),
  'room',jsonb_build_object('name',r.name,'createdAt',r.created_at,'giftedCharacterIds',to_jsonb(r)->'gifted_character_ids'),
  'participants',coalesce((select jsonb_agg(to_jsonb(p)-'auth_user_id'-'device_id'-'room_id' order by p.joined_at) from public.room_participants p where p.room_id=r.id),'[]'::jsonb),
  'rolls',coalesce((select jsonb_agg(to_jsonb(roll)-'auth_user_id'-'device_id'-'room_id' order by roll.created_at,roll.id) from public.room_rolls roll where roll.room_id=r.id),'[]'::jsonb),
  'requests',coalesce((select jsonb_agg(to_jsonb(req)-'room_id' order by req.created_at,req.id) from public.room_requests req where req.room_id=r.id),'[]'::jsonb),
  'combat',(select c.state-'relationshipWeb' from public.room_combat c where c.room_id=r.id),
  'relationships',(select graph.data from public.room_relationships graph where graph.room_id=r.id)
 ) into archive from public.rooms r where r.id=p_room_id;
 return archive;
end;$$;
revoke all on function public.export_room_archive(uuid) from public,anon;
grant execute on function public.export_room_archive(uuid) to authenticated;

do $$begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='room_relationships') then
  alter publication supabase_realtime add table public.room_relationships;
 end if;
end;$$;

-- Preserve old room links and embedded NPC cards when upgrading from combat JSON.
insert into public.room_relationships(room_id,data)
select c.room_id,jsonb_build_object('version',1,
 'links','[{"id":"book:R01","characterId":"organization:асгард","characterName":"Асгард","sourceType":"organization","targetId":"organization:гардарика","targetName":"Гардарика","targetType":"organization","relation":"союз · Обряды и защита","notes":"Асгард поддерживает союз духовным авторитетом; Гардарика обеспечивает пути и охрану. Города не передают Совету светскую власть.\nПовод для перемены: Совет требует изменить решение князя, а тот ссылается на право города."},{"id":"book:R02","characterId":"organization:асгард","characterName":"Асгард","sourceType":"organization","targetId":"organization:вечевые земли","targetName":"Вечевые земли","targetType":"organization","relation":"спор · Авторитет без подчинения","notes":"Вече уважает северные знания, но принимает местные решения самостоятельно.\nПовод для перемены: Посланник выдаёт рекомендацию волхвов за обязательный приказ."},{"id":"book:R03","characterId":"organization:гардарика","characterName":"Гардарика","sourceType":"organization","targetId":"organization:вечевые земли","targetName":"Вечевые земли","targetType":"organization","relation":"обмен · Торг и общая дорога","notes":"Крепости и общины нуждаются в торговле и безопасности дорог. Размер совместных расходов обсуждается заново.\nПовод для перемены: Одна сторона перекладывает ремонт моста на другую."},{"id":"book:R04","characterId":"organization:харитония","characterName":"Харитония","sourceType":"organization","targetId":"organization:вольница","targetName":"Вольница","targetType":"organization","relation":"спор · Подати и свобода","notes":"Соседи могут защищать степь вместе, но спорят о подчинении общин.\nПовод для перемены: Вольная община принимает людей, которых царский управитель считает своими должниками."},{"id":"book:R05","characterId":"organization:харитония","characterName":"Харитония","sourceType":"organization","targetId":"organization:рубежи","targetName":"Рубежи","targetType":"organization","relation":"обмен · Снабжение без подчинения","notes":"Харитония даёт людей, коней и пищу; Рубежи сохраняют собственное управление.\nПовод для перемены: Поставщик требует назначить своего коменданта за продовольственную помощь."},{"id":"book:R06","characterId":"organization:волки","characterName":"Волки","sourceType":"organization","targetId":"organization:степные щиты","targetName":"Степные Щиты","targetType":"organization","relation":"соперничество · Степные пути и добыча","notes":"Набеги Волков сталкиваются с охранными договорами Щитов; условия мира зависят от воды и пастбищ.\nПовод для перемены: Караван идёт через единственный водопой кочевников."},{"id":"book:R07","characterId":"organization:золотая подкова","characterName":"Золотая Подкова","sourceType":"organization","targetId":"organization:степные щиты","targetName":"Степные Щиты","targetType":"organization","relation":"обмен · Плата за сопровождение","notes":"Подкова оплачивает проводников и охрану; Щиты отвечают за согласованный участок пути, а не за всю степь.\nПовод для перемены: Приказчик меняет маршрут, сохранив прежнюю оплату."},{"id":"book:R08","characterId":"organization:золотая подкова","characterName":"Золотая Подкова","sourceType":"organization","targetId":"organization:гардарика","targetName":"Гардарика","targetType":"organization","relation":"обмен · Пошлины и безопасность","notes":"Купцы оплачивают дороги и охрану, а города гарантируют объявленные правила торга.\nПовод для перемены: Новый сбор появляется после выхода каравана."},{"id":"book:R09","characterId":"organization:серебряные щиты","characterName":"Серебряные Щиты","sourceType":"organization","targetId":"organization:гардарика","targetName":"Гардарика","targetType":"organization","relation":"соперничество · Право на военный найм","notes":"Княжеские дружины и братство конкурируют за контракты; в кризис могут совместно оборонять город.\nПовод для перемены: Воевода требует подчинить наёмный отряд после окончания договора."},{"id":"book:R10","characterId":"organization:золотая подкова","characterName":"Золотая Подкова","sourceType":"organization","targetId":"organization:тёмные ключники","targetName":"Тёмные Ключники","targetType":"organization","relation":"вражда · Кражи и тайный рынок","notes":"Кражи подрывают доходы купцов; информация иногда создаёт основания для временного торга.\nПовод для перемены: Пропадает долговая книга, которую обе стороны хотят получить первой."},{"id":"book:R11","characterId":"organization:круг ищущих","characterName":"Круг Ищущих","sourceType":"organization","targetId":"organization:свечи предвечного","targetName":"Свечи Предвечного","targetType":"organization","relation":"спор · Исследование и запреты","notes":"Условия книги допускают конкуренцию; здесь спор возникает вокруг конкретных опасных опытов, а не всей магии.\nПовод для перемены: Очищение уничтожит образец, нужный для исследования."},{"id":"book:R12","characterId":"organization:свечи предвечного","characterName":"Свечи Предвечного","sourceType":"organization","targetId":"organization:культ чёрного поля","targetName":"Культ Чёрного Поля","targetType":"organization","relation":"вражда · Тлен и очищение","notes":"Братство противостоит конкретному культу, использующему слабые места границы миров.\nПовод для перемены: Культ прячется за обвинениями против невиновных изгоев."},{"id":"book:R13","characterId":"organization:круг ищущих","characterName":"Круг Ищущих","sourceType":"organization","targetId":"organization:чудинцы","targetName":"Чудинцы","targetType":"organization","relation":"обмен · Архивы и приборы","notes":"Круг даёт обрядовые и магические знания, артели - приборы и полевое исследование.\nПовод для перемены: Стороны спорят, кому принадлежат записи экспедиции."},{"id":"book:R14","characterId":"organization:чудинцы","characterName":"Чудинцы","sourceType":"organization","targetId":"organization:пробуждённые","targetName":"Пробуждённые","targetType":"organization","relation":"спор · Познание и согласие","notes":"Интерес чудинцев к устройству механизмов указан в книге; требование согласия и конкретный конфликт предложены.\nПовод для перемены: Исследователь называет личную память Пробуждённого общедоступным древним архивом."},{"id":"book:R15","characterId":"organization:сварожичи","characterName":"Сварожичи","sourceType":"organization","targetId":"organization:пробуждённые","targetName":"Пробуждённые","targetType":"organization","relation":"обмен · Ремонт и родовые тайны","notes":"Уважение с опаской взято из книги; обмен работой, ремонтом и правом хранить память предложен.\nПовод для перемены: Кузня требует копию памяти в качестве платы за недостающую деталь."},{"id":"book:R16","characterId":"organization:лесовики","characterName":"Лесовики","sourceType":"organization","targetId":"organization:пробуждённые","targetName":"Пробуждённые","targetType":"organization","relation":"спор · Чуждая Жива и соседство","notes":"Книга отмечает чужеродность механизмов для лесовиков; правила прохода через рощу предложены.\nПовод для перемены: Древняя программа ведёт Пробуждённого через закрытое священное место."},{"id":"book:R17","characterId":"organization:вечевые земли","characterName":"Вечевые земли","sourceType":"organization","targetId":"organization:лесовики","targetName":"Лесовики","targetType":"organization","relation":"спор · Дорога и священная роща","notes":"Соседство подтверждено книгой; промысловые договоры должны заключаться с конкретными хранителями.\nПовод для перемены: Вече выдаёт разрешение на вырубку леса, который не принадлежит общине."},{"id":"book:R18","characterId":"organization:сварожичи","characterName":"Сварожичи","sourceType":"organization","targetId":"organization:лесовики","targetName":"Лесовики","targetType":"organization","relation":"обмен · Топливо и пределы промысла","notes":"Кузни нуждаются в топливе, хранители допускают выборочный промысел в согласованных местах.\nПовод для перемены: Новый заказ металла увеличивает вырубку сверх договора."},{"id":"book:R19","characterId":"organization:полевички","characterName":"Полевички","sourceType":"organization","targetId":"organization:золотая подкова","targetName":"Золотая Подкова","targetType":"organization","relation":"спор · Хлеб и кредит","notes":"Купцы вывозят урожай и дают кредит; полевички защищают семенной запас.\nПовод для перемены: Неурожай превращает прежнюю расписку в требование отдать семена."},{"id":"book:R20","characterId":"organization:общины людей","characterName":"Общины людей","sourceType":"organization","targetId":"organization:полевички","targetName":"Полевички","targetType":"organization","relation":"союз · Соседская помощь","notes":"Конкретные человеческие и полевые общины объединяют хозяйственные работы и защиту посевов.\nПовод для перемены: Старый межевой спор всплывает после совместного спасения урожая."},{"id":"book:R21","characterId":"organization:общины людей","characterName":"Общины людей","sourceType":"organization","targetId":"organization:харитония","targetName":"Харитония","targetType":"organization","relation":"спор · Подать и выживание","notes":"Узел касается человеческих общин Харитонии; он не означает власть царства над всеми людьми.\nПовод для перемены: Сбор податей не учитывает уже отданные на фронтир припасы."},{"id":"book:R22","characterId":"organization:общины людей","characterName":"Общины людей","sourceType":"organization","targetId":"organization:вольные ведуны","targetName":"Вольные ведуны","targetType":"organization","relation":"союз · Помощь и местный обет","notes":"Соседи поддерживают ведуна пищей и трудом, ведун помогает с хворью и отношениями с местными духами.\nПовод для перемены: Община требует чуда, которое нарушит личный обет помощника."},{"id":"book:R23","characterId":"organization:асгард","characterName":"Асгард","sourceType":"organization","targetId":"organization:вольные ведуны","targetName":"Вольные ведуны","targetType":"organization","relation":"спор · Признание и самостоятельность","notes":"Асгард предлагает обучение и поручительство, местные ведуны опасаются обязательного надзора.\nПовод для перемены: Признание связывают с выдачей чужих обрядовых тайн."},{"id":"book:R24","characterId":"organization:вольные ведуны","characterName":"Вольные ведуны","sourceType":"organization","targetId":"organization:лесовики","targetName":"Лесовики","targetType":"organization","relation":"союз · Знание мест и обеты","notes":"Местные хранители и ведуны помогают друг другу через личные договорённости.\nПовод для перемены: Один старый договор начинают толковать как право на весь лес."},{"id":"book:R25","characterId":"organization:свечи предвечного","characterName":"Свечи Предвечного","sourceType":"organization","targetId":"organization:тени рода","targetName":"Тени Рода","targetType":"organization","relation":"спор · Подозрение и заступничество","notes":"Заступники защищают невиновных, строгие служители требуют проверок; происхождение само по себе не доказывает вину.\nПовод для перемены: После навьего происшествия требуют задержать всех отмеченных."},{"id":"book:R26","characterId":"organization:тёмные ключники","characterName":"Тёмные Ключники","sourceType":"organization","targetId":"organization:тени рода","targetName":"Тени Рода","targetType":"organization","relation":"обмен · Укрытие и зависимость","notes":"Ключники дают некоторым изгнанникам ночлег за услуги; круг взаимопомощи стремится освободиться от такого долга.\nПовод для перемены: Хозяин укрытия требует участвовать в ограблении вместо платы."},{"id":"book:R27","characterId":"organization:тени рода","characterName":"Тени Рода","sourceType":"organization","targetId":"organization:культ чёрного поля","targetName":"Культ Чёрного Поля","targetType":"organization","relation":"вражда · Вербовка и отказ","notes":"Культ использует уязвимость изгнанников; круг сопротивляется вербовке и собирает доказательства.\nПовод для перемены: Помощь семье оказывается ловушкой с требованием нового преступления."},{"id":"book:R28","characterId":"organization:рубежи","characterName":"Рубежи","sourceType":"organization","targetId":"organization:драконьи потомки","targetName":"Драконьи Потомки","targetType":"organization","relation":"союз · Мир и защита границы","notes":"Посольство предлагает ограниченную помощь против Тлена; Рубежи обязуются уважать закрытые поселения.\nПовод для перемены: Военный штаб требует секретные пути в обмен на охрану послов."},{"id":"book:R29","characterId":"organization:драконьи потомки","characterName":"Драконьи Потомки","sourceType":"organization","targetId":"organization:асгард","targetName":"Асгард","targetType":"organization","relation":"спор · Две памяти древнего мира","notes":"Обе стороны хранят предания о мире; ни один архив здесь не объявлен единственным истинным.\nПовод для перемены: Несовпадение копий используют как доказательство намеренного обмана."},{"id":"book:R30","characterId":"organization:аримия","characterName":"Аримия","sourceType":"organization","targetId":"organization:золотая подкова","targetName":"Золотая Подкова","targetType":"organization","relation":"обмен · Редкий заморский торг","notes":"Редкая торговля подтверждена книгой; контакт через Подкову и его условия предложены.\nПовод для перемены: Купеческий дом скрывает происхождение товара, чтобы не потерять рынок."},{"id":"book:R31","characterId":"organization:аримия","characterName":"Аримия","sourceType":"organization","targetId":"organization:рубежи","targetName":"Рубежи","targetType":"organization","relation":"спор · Память войны и пропуск","notes":"Сохраняются подозрения после войны; контакт проходит через морской путь и восточные крепости.\nПовод для перемены: Торгового посредника принимают за разведчика по старому военному знаку."},{"id":"book:R32","characterId":"organization:культ чёрного поля","characterName":"Культ Чёрного Поля","sourceType":"organization","targetId":"organization:рубежи","targetName":"Рубежи","targetType":"organization","relation":"вражда · Пустоши и оборонительный пояс","notes":"Конкретная группа пытается нарушить защиту крепостей; не все жители и исследователи Пустошей принадлежат культу.\nПовод для перемены: Исчезают отметки безопасного пути, снабжение заходит в опасную зону."},{"id":"book:R33","characterId":"organization:свечи предвечного","characterName":"Свечи Предвечного","sourceType":"organization","targetId":"organization:пробуждённые","targetName":"Пробуждённые","targetType":"organization","relation":"спор · Душа и право на обет","notes":"Спор жрецов о душе механизма указан в книге; братство рассматривает конкретное дело Пробуждённого.\nПовод для перемены: Служитель отказывает в убежище существу, уже давшему защитный обет."},{"id":"book:R34","characterId":"organization:сварожичи","characterName":"Сварожичи","sourceType":"organization","targetId":"organization:серебряные щиты","targetName":"Серебряные Щиты","targetType":"organization","relation":"обмен · Оружие и честная плата","notes":"Кузни снабжают братство; бойцы защищают перевозки и помогают взыскивать долги без присвоения чертежей.\nПовод для перемены: Заказчик скрывает брак, чтобы переложить ущерб на сказителя."},{"id":"book:R35","characterId":"organization:вольница","characterName":"Вольница","sourceType":"organization","targetId":"organization:степные щиты","targetName":"Степные Щиты","targetType":"organization","relation":"обмен · Стоянки и проводники","notes":"Вольница предоставляет согласованные стоянки, Щиты открывают сезонные пути и берут охранные контракты.\nПовод для перемены: Часть проводников перекрывает брод ради двойной платы."},{"id":"book:R36","characterId":"organization:волки","characterName":"Волки","sourceType":"organization","targetId":"organization:харитония","targetName":"Харитония","targetType":"organization","relation":"вражда · Набеги и водопои","notes":"Набеги на оседлые земли подтверждены книгой; водный спор с Харитонией - предложение для кампании.\nПовод для перемены: Управитель ограждает водопой, а набег затем называют беспричинным."},{"id":"book:R37","characterId":"organization:вечевые земли","characterName":"Вечевые земли","sourceType":"organization","targetId":"organization:полевички","targetName":"Полевички","targetType":"organization","relation":"обмен · Община и право голоса","notes":"Полевые общины договариваются с соседними вечами; представительство должно быть признано отдельным решением.\nПовод для перемены: Посевы общины учитывают в налогах, но её посланника не допускают к обсуждению."},{"id":"book:R38","characterId":"organization:вольные ведуны","characterName":"Вольные ведуны","sourceType":"organization","targetId":"organization:круг ищущих","targetName":"Круг Ищущих","targetType":"organization","relation":"спор · Устное знание и запись","notes":"Круг предлагает сохранить местные знания; ведуны ограничивают распространение обрядов, связанных обетами.\nПовод для перемены: Учёный публикует личный договор с духом как общедоступный способ призыва."},{"id":"book:R39","characterId":"organization:круг ищущих","characterName":"Круг Ищущих","sourceType":"organization","targetId":"organization:рубежи","targetName":"Рубежи","targetType":"organization","relation":"обмен · Разведка и опасные образцы","notes":"Гарнизон открывает доступ к экспедициям, исследователи помогают понимать аномалии; опасные грузы проверяются.\nПовод для перемены: Учёный требует вывезти образец, нарушающий условия пропуска."},{"id":"book:R40","characterId":"organization:гардарика","characterName":"Гардарика","sourceType":"organization","targetId":"organization:общины людей","targetName":"Общины людей","targetType":"organization","relation":"спор · Оборона и повинности","notes":"Конкретные общины Гардарики дают людей и труд на оборону; порядок повинностей остаётся предметом спора.\nПовод для перемены: Воевода продлевает временные работы на крепости без нового согласия."},{"id":"book:R41","characterId":"organization:общины людей","characterName":"Общины людей","sourceType":"organization","targetId":"organization:тени рода","targetName":"Тени Рода","targetType":"organization","relation":"спор · Страх и соседское свидетельство","notes":"Одни соседи требуют изгнания отмеченных, другие готовы поручиться за тех, кого знают лично.\nПовод для перемены: Обвинение появляется одновременно с попыткой захватить дом изгнанника."},{"id":"book:R42","characterId":"organization:драконьи потомки","characterName":"Драконьи Потомки","sourceType":"organization","targetId":"organization:аримия","targetName":"Аримия","targetType":"organization","relation":"спор · Посредничество и старые архивы","notes":"Послы сравнивают свидетельства прежних войн; Драконьи Потомки не отождествляются с Аримией.\nПовод для перемены: Имперская миссия пытается получить исключительное право говорить от имени всех восточных народов."}]'::jsonb || (c.state->'relationshipWeb'),
 'npcs',jsonb_path_query_array(c.state,'$.relationshipWeb[*].targetNpc') || jsonb_path_query_array(c.state,'$.relationshipWeb[*].sourceNpc'))
from public.room_combat c where jsonb_typeof(c.state->'relationshipWeb')='array'
